def runningTotal0(firstValues, limitValue):
    """Total number 0."""
    accumulatedTotal = 0
    accumulatedTotal += firstValues[0] * 2
    accumulatedTotal += firstValues[1] * 2
    accumulatedTotal += firstValues[2] * 2

    accumulatedTotal += firstValues[3] * 2
    accumulatedTotal += firstValues[4] * 2
    accumulatedTotal += firstValues[5] * 2

    accumulatedTotal += firstValues[6] * 2
    accumulatedTotal += firstValues[7] * 2
    accumulatedTotal += firstValues[8] * 2

    accumulatedTotal += firstValues[9] * 2
    accumulatedTotal += firstValues[10] * 2
    accumulatedTotal += firstValues[11] * 2

    accumulatedTotal += firstValues[12] * 2
    accumulatedTotal += firstValues[13] * 2
    accumulatedTotal += firstValues[14] * 2

    accumulatedTotal += firstValues[15] * 2
    accumulatedTotal += firstValues[16] * 2
    accumulatedTotal += firstValues[17] * 2

    accumulatedTotal += firstValues[18] * 2
    accumulatedTotal += firstValues[19] * 2
    accumulatedTotal += firstValues[20] * 2

    accumulatedTotal += firstValues[21] * 2
    accumulatedTotal += firstValues[22] * 2
    accumulatedTotal += firstValues[23] * 2

    return min(accumulatedTotal, limitValue)


